		correct: "500",
		hint: "<p>Дуга — полуокружность длиной 7,85 м. Длина полуокружности = πR = 7,85, значит R = 7,85/3,14 = 2,5 м. Ширина MN — это диаметр = 2R = 5 м = 500 см.</p>",
