		hint: "<p>AB ∥ DC, поэтому треугольники ABM и CDM подобны (накрест лежащие углы при секущих). Коэффициент подобия k = DC/AB = 30/15 = 2. Точка M делит AC так, что AM : MC = AB : DC = 15 : 30 = 1 : 2. Значит MC = (2/3)·AC = (2/3)·39 = 26.</p>",
