		type: "written",
		title: "Часть 2 · Планиметрия (доказательство)",
		body: "<p>В треугольнике ABC с тупым углом ABC проведены высоты AA₁ и CC₁. Докажите, что треугольники A₁BC₁ и ABC подобны.</p>",
		maxPoints: 2,
		hint: "<p>Высоты AA₁ и CC₁ опущены на продолжения сторон (угол B тупой). В прямоугольном треугольнике A₁BA: BA₁ = AB·|cos(∠A₁BA)|. Угол A₁BA смежен с углом ABC, поэтому |cos∠A₁BA| = |cos B|. Аналогично из прямоугольного треугольника C₁BC: BC₁ = BC·|cos B|.</p><p>Рассмотрим треугольники A₁BC₁ и CBA. У них общий угол при вершине B (вертикальные/смежные совпадают по величине), и стороны, прилежащие к нему, пропорциональны:</p><p>BA₁/BC = (AB·|cos B|)/BC и BC₁/BA = (BC·|cos B|)/BA.</p><p>Отсюда BA₁/BC = BC₁/BA = |cos B| — две стороны пропорциональны и угол между ними равен. По признаку подобия (две стороны и угол между ними) треугольники A₁BC₁ и CBA (то есть ABC) подобны с коэффициентом |cos B|. Что и требовалось доказать.</p>",
