		body: "<p>В треугольнике ABC известны длины сторон AB = 30, AC = 100, точка O — центр окружности, описанной около треугольника ABC. Прямая BD, перпендикулярная прямой AO, пересекает сторону AC в точке D. Найдите CD.</p>",
		maxPoints: 2,
		hint: "<p>Введём систему координат: A в начале, сторона AC вдоль оси Ox, тогда C = (100; 0), а B где-то выше оси. O — центр описанной окружности (точка пересечения серединных перпендикуляров). Прямая AO проведена из A в центр O. Перпендикуляр BD к прямой AO, опущенный из B, пересекает AC в точке D.</p><p>Ключевой факт: при отражении относительно прямой AO окружность переходит в себя (AO проходит через центр), и точка B отражается в точку B′ окружности, причём дуга и хорда сохраняются. Проекция приводит к соотношению AD = AB²/AC.</p><p>Действительно, прямой счёт (не зависящий от угла A) даёт x-координату точки D, равную AB²/AC = 30²/100 = 900/100 = 9, то есть AD = 9. Тогда CD = AC − AD = 100 − 9 = 91. Ответ: 91.</p>",
