		body: "<p>Из двух городов одновременно навстречу друг другу отправились два велосипедиста. Проехав некоторую часть пути, первый велосипедист сделал остановку на 2 минуты, а затем продолжил движение до встречи со вторым велосипедистом. Расстояние между городами составляет 277 км, скорость первого велосипедиста равна 16 км/ч, скорость второго — 30 км/ч. Определите расстояние от города, из которого выехал второй велосипедист, до места встречи.</p>",
		maxPoints: 2,
		hint: "<p>Пусть до встречи прошло t часов. Второй ехал без остановок: путь = 30t. Первый стоял 2 мин = 1/30 ч, в движении был (t − 1/30) ч: путь = 16(t − 1/30). Сумма = 277:</p><p>16(t − 1/30) + 30t = 277 ⟹ 46t − 16/30 = 277 ⟹ 46t = 277 + 16/30 ⟹ t = 181/30 ч.</p><p>Расстояние от города 2 = 30t = 30·181/30 = 181 км. Ответ: 181 км.</p>",
