		title: "Часть 2 · Планиметрия (доказательство)",
		body: "<p>В треугольнике ABC с тупым углом ACB проведены высоты AA₁ и BB₁. Докажите, что треугольники A₁CB₁ и ACB подобны.</p>",
		maxPoints: 2,
