		body: "<p>Общепринятые форматы листов бумаги обозначают буквой A и цифрой: A0, A1, A2 и так далее. Лист формата A0 имеет форму прямоугольника площадью 1 кв. м. Если лист формата A0 разрезать пополам параллельно меньшей стороне, получатся два одинаковых листа формата A1, и так далее. Отношение большей стороны к меньшей у всех форматов одно и то же, поэтому листы подобны.<br>В таблице даны размеры (с точностью до мм) четырёх листов форматов A1, A3, A4 и A5:<br>  лист 1: 420 × 297<br>  лист 2: 297 × 210<br>  лист 3: 841 × 594<br>  лист 4: 210 × 148<br>Установите соответствие между форматами и номерами листов. Запишите в ответ последовательность четырёх цифр (номеров листов) для форматов A1, A3, A4, A5.</p><figure class=\"q-figure\"><img class=\"q-figure__img\" src=\"/img/mathematics/v8_formats.png\" alt=\"Иллюстрация к заданию ОГЭ по математике\" loading=\"lazy\" decoding=\"async\" /></figure>",
