		title: "Часть 2 · Уравнение",
		body: "<p>Решите уравнение |(x − 2)(5x − 1)| + √(5x³ + 24x² − 1) = 0.</p>",
		maxPoints: 2,
		hint: "<p>Сумма модуля и арифметического корня (оба неотрицательны) равна нулю только если оба слагаемых равны нулю одновременно.</p><p>|(x−2)(5x−1)| = 0 ⟹ x = 2 или x = 1/5.</p><p>√(5x³ + 24x² − 1) = 0 ⟹ 5x³ + 24x² − 1 = 0.</p><p>Проверяем: при x = 2: 5·8 + 24·4 − 1 = 40 + 96 − 1 = 135 ≠ 0. При x = 1/5: 5·(1/125) + 24·(1/25) − 1 = 1/25 + 24/25 − 1 = 25/25 − 1 = 0 ✓.</p><p>Обоим условиям удовлетворяет только x = 1/5 = 0,2. Ответ: 0,2.</p>",
