		body: "<p>В параллелограмме ABCD проведена диагональ AC. Точка O является центром окружности, вписанной в треугольник ABC. Расстояния от точки O до точки A и прямых AD и AC соответственно равны 25, 15 и 7. Найдите площадь параллелограмма ABCD.</p>",
		maxPoints: 2,
		hint: "<p>O — центр вписанной в треугольник ABC окружности, поэтому расстояние от O до любой стороны треугольника равно радиусу r = 7 (в частности до AC).</p><p>Расстояние OA = 25 и расстояние до AC = 7 связаны через половину угла BAC: sin(∠BAC/2) = 7/25, откуда cos(∠BAC/2) = 24/25, и sin∠BAC = 2·(7/25)·(24/25) = 336/625, cos∠BAC = 1 − 2·(7/25)² = 527/625.</p><p>Третье условие — расстояние от O до прямой AD равно 15 — определяет форму. Введя координаты (A в начале, AB вдоль оси) и записав условия «O — инцентр, dist(O,AC)=7, dist(O,AD)=15, OA=25», получаем стороны AB и AC и угол при A, а площадь параллелограмма S = AB·AC·sin∠BAC.</p><p>Прямой расчёт даёт S = 924. Ответ: 924.</p>",
