		body: "<p>Иван Викторович решил построить на дачном участке теплицу длиной 4,2 метра. Для этого он сделал прямоугольный фундамент. Для каркаса теплицы Иван Викторович заказывает металлические дуги в форме полуокружностей длиной 4,71 м каждая и плёнку для обтяжки. В передней стенке планируется вход, показанный на рисунке прямоугольником ACDB. Точки A и B — соответственно середины отрезков MO и ON.</p><p>Какое наименьшее количество дуг нужно заказать, чтобы расстояние между соседними дугами было не более 50 см?</p><figure class=\"q-figure\"><img class=\"q-figure__img\" src=\"/img/mathematics/v9_teplica.png\" alt=\"Иллюстрация к заданию ОГЭ по математике\" loading=\"lazy\" decoding=\"async\" /></figure>",
