		title: "Часть 2 · Текстовая задача",
		body: "<p>Из двух городов одновременно навстречу друг другу отправились два велосипедиста. Проехав некоторую часть пути, первый велосипедист сделал остановку на 48 минут, а затем продолжил движение до встречи со вторым велосипедистом. Расстояние между городами составляет 168 км, скорость первого велосипедиста равна 15 км/ч, скорость второго — 30 км/ч. Определите расстояние от города, из которого выехал второй велосипедист, до места встречи.</p>",
		maxPoints: 2,
		hint: "<p>Пусть до встречи прошло t часов. Второй ехал без остановок: путь = 30t. Первый стоял 48 мин = 4/5 ч, в движении был (t − 4/5) ч: путь = 15(t − 4/5). Сумма = 168:</p><p>15(t − 4/5) + 30t = 168 ⟹ 45t − 12 = 168 ⟹ 45t = 180 ⟹ t = 4 ч.</p><p>Расстояние от города 2 = 30·4 = 120 км. Ответ: 120 км.</p>",
