		title: "Часть 2 · Планиметрия (доказательство)",
		body: "<p>В треугольнике ABC с тупым углом BAC проведены высоты BB₁ и CC₁. Докажите, что треугольники AB₁C₁ и ABC подобны.</p>",
		maxPoints: 2,
		hint: "<p>Высоты BB₁ и CC₁ опущены на продолжения сторон (угол A тупой). В прямоугольном треугольнике AB₁B: AB₁ = AB·|cos A| (угол B₁AB смежен с A). В прямоугольном треугольнике AC₁C: AC₁ = AC·|cos A|.</p><p>В треугольниках AB₁C₁ и ABC угол при A общий (по величине), и прилежащие стороны пропорциональны: AB₁/AC = AC₁/AB = |cos A|. По признаку «две стороны и угол между ними» треугольники AB₁C₁ и ACB (то есть ABC) подобны. Что и требовалось доказать.</p>",
