		title: "Часть 2 · Планиметрия (вычисление)",
		body: "<p>В треугольнике ABC известны длины сторон AB = 28, AC = 56, точка O — центр окружности, описанной около треугольника ABC. Прямая BD, перпендикулярная прямой AO, пересекает сторону AC в точке D. Найдите CD.</p>",
		maxPoints: 2,
		hint: "<p>Поместим A в начало координат, AC вдоль оси Ox: C = (56; 0). Перпендикуляр из B на прямую AO пересекает AC в точке D. Прямой расчёт (результат не зависит от угла A) даёт AD = AB²/AC = 28²/56 = 784/56 = 14. Тогда CD = AC − AD = 56 − 14 = 42. Ответ: 42.</p>",
