		hint: "<p>Склон — прямоугольный треугольник с катетами 16 м (высота) и 63 м (основание). Длина склона (гипотенуза) = √(16² + 63²) = √(256 + 3969) = √4225 = 65 м. Площадь склона = ширина · длина = 50 · 65 = 3250 м².</p>",
