		body: "<p>Из A в B одновременно выехали два автомобилиста. Первый проехал с постоянной скоростью весь путь. Второй проехал первую половину пути со скоростью 55 км/ч, а вторую половину пути — со скоростью, большей скорости первого на 6 км/ч, в результате чего прибыл в B одновременно с первым автомобилистом. Найдите скорость первого автомобилиста.</p>",
