		body: "<p>Постройте график функции y = 2|x − 4| − x² + 9x − 20 и определите, при каких значениях m прямая y = m имеет с графиком ровно три общие точки.</p>",
		maxPoints: 2,
		hint: "<p>Раскроем модуль.</p><p>• При x ≥ 4: y = 2(x − 4) − x² + 9x − 20 = −x² + 11x − 28 (парабола вниз, вершина в x = 5,5, y = 2,25).</p><p>• При x &lt; 4: y = −2(x − 4) − x² + 9x − 20 = −x² + 7x − 12 (парабола вниз, вершина в x = 3,5, y = 0,25).</p><p>В точке стыка x = 4 обе части дают y = 0.</p><p>График: слева возрастает до локального максимума 0,25 (x=3,5), спадает к 0 при x=4, затем правая ветвь возрастает до максимума 2,25 (x=5,5) и спадает.</p><p>Число точек пересечения с y = m:</p><p>– m &lt; 0: 2;</p><p>– m = 0: 3 (касание стыка снизу даёт три точки: x=3, x=4, x=7);</p><p>– 0 &lt; m &lt; 0,25: 4 (левая парабола 2 точки + правая 2 точки);</p><p>– m = 0,25: 3 (левая — касание в вершине, правая — 2 точки);</p><p>– 0,25 &lt; m &lt; 2,25: 2;</p><p>– m = 2,25: 1; m &gt; 2,25: 0.</p><p>Ровно три общие точки при m = 0 и m = 0,25.</p>",
