		body: "<p>Основания BC и AD трапеции ABCD равны соответственно 8 и 18, BD = 12. Докажите, что треугольники CBD и BDA подобны.</p>",
		maxPoints: 2,
		hint: "<p>В трапеции BC ∥ AD, поэтому ∠CBD = ∠BDA как накрест лежащие при секущей BD.</p><p>Рассмотрим треугольники CBD и BDA. У них есть равные углы (∠CBD = ∠BDA), а стороны, прилежащие к этим углам, пропорциональны:</p><p>BC/DA = 8/18 = 4/9 и BD/AD … проверим отношение BC/BD и BD/DA:</p><p>BC/BD = 8/12 = 2/3, BD/DA = 12/18 = 2/3.</p><p>Значит BC/BD = BD/DA = 2/3, и угол между этими сторонами общий (∠CBD = ∠BDA). По признаку подобия «две стороны пропорциональны и угол между ними равен» треугольники CBD и BDA подобны. Что и требовалось доказать.</p>",
