		title: "Часть 2 · Планиметрия (вычисление)",
		body: "<p>В равнобедренную трапецию, периметр которой равен 120, а площадь равна 540, можно вписать окружность. Найдите расстояние от точки пересечения диагоналей трапеции до её меньшего основания.</p>",
		maxPoints: 2,
		hint: "<p>В трапецию можно вписать окружность ⟺ сумма оснований равна сумме боковых сторон: a + b = 2c (c — боковая сторона). Периметр = (a + b) + 2c = 2(a + b) = 120 ⟹ a + b = 60.</p><p>Площадь = ((a + b)/2)·h = 30h = 540 ⟹ h = 18 (это и диаметр вписанной окружности).</p><p>Боковая сторона c = (a + b)/2 = 30. Высота 18, проекция боковой на основание (a − b)/2: c² = h² + ((a−b)/2)² ⟹ 900 = 324 + ((a−b)/2)² ⟹ ((a−b)/2)² = 576 ⟹ (a−b)/2 = 24 ⟹ a − b = 48. С a + b = 60 получаем a = 54 (большее), b = 6 (меньшее).</p><p>Диагонали делятся точкой пересечения в отношении оснований b : a от меньшего основания. Расстояние от точки пересечения до меньшего основания = h·b/(a + b) = 18·6/60 = 1,8.</p>",
