		body: "<p>На плане изображён дачный участок (СНТ «Рассвет», ул. Центральная, д. 32). Сторона каждой клетки равна 2 м. Площадь жилого дома 64 кв. м, баня 36 кв. м. Объекты на плане: ① — жилой дом, ② — цветник, ③ — теплица, ④ — баня, ⑤ — бак с водой, ⑥ — огород (овощи), ⑦ — плодово-ягодные кустарники.<br>Для объектов из таблицы определите, какими цифрами они обозначены на плане. В ответ запишите последовательность четырёх цифр для объектов: баня, жилой дом, кустарники, бак с водой.</p><figure class=\"q-figure\"><img class=\"q-figure__img\" src=\"/img/mathematics/v12_plan.png\" alt=\"Иллюстрация к заданию ОГЭ по математике\" loading=\"lazy\" decoding=\"async\" /></figure>",
