		body: "<p>Хозяин участка планирует установить систему отопления и рассматривает два варианта: электрическое или газовое. Данные:<br>  Газовое: котёл 20000 руб., прочее оборудование и монтаж 12095 руб., расход 1,6 куб. м/ч, цена газа 4,6 руб./куб. м.<br>  Электрическое: котёл 17000 руб., прочее 10000 руб., мощность 4,5 кВт, цена 3,9 руб./(кВт·ч).<br>Через сколько часов непрерывной работы отопления экономия от использования газа вместо электричества компенсирует разницу в стоимости оборудования с учётом установки?</p>",
