		title: "Часть 2 · Текстовая задача",
		body: "<p>Два автомобиля одновременно отправляются в 950-километровый пробег. Первый едет со скоростью на 18 км/ч большей, чем второй, и прибывает к финишу на 4 ч раньше второго. Найдите скорость первого автомобиля.</p>",
		maxPoints: 2,
