		type: "written",
		title: "Часть 2 · График функции",
		body: "<p>Постройте график функции y = ((x² + 1)(x − 2)) / (2 − x) и определите, при каких значениях k прямая y = kx имеет с графиком ровно одну общую точку.</p>",
		maxPoints: 2,
