		body: "<p>Прямая, параллельная основаниям трапеции ABCD, пересекает её боковые стороны AB и CD в точках E и F соответственно. Найдите длину отрезка EF, если AD = 50, BC = 30, CF : DF = 7 : 3.</p>",
		maxPoints: 2,
		hint: "<p>Отрезок EF параллелен основаниям. Точка F делит боковую сторону CD так, что CF : FD = 7 : 3 (считая от вершины C при меньшем основании BC = 30 к вершине D при большем основании AD = 50). Длина EF линейно зависит от положения: EF = BC + (AD − BC)·(CF/(CF + FD)) = 30 + (50 − 30)·(7/10) = 30 + 14 = 44.</p>",
