		type: "input",
		title: "Практическое задание",
		body: "<p>На плане изображён дачный участок (СНТ «Рассвет», ул. Центральная, д. 32). Сторона клетки 2 м. Баня 36 кв. м. Объекты: ① — жилой дом, ② — цветник, ③ — теплица, ④ — баня, ⑤ — бак с водой, ⑥ — огород, ⑦ — плодово-ягодные кустарники.<br>Определите, какими цифрами обозначены на плане объекты: кустарники, баня, бак с водой, жилой дом. Запишите последовательность четырёх цифр.</p><figure class=\"q-figure\"><img class=\"q-figure__img\" src=\"/img/mathematics/v13_plan.png\" alt=\"Иллюстрация к заданию ОГЭ по математике\" loading=\"lazy\" decoding=\"async\" /></figure>",
