		maxPoints: 2,
		hint: "<p>Пусть скорость первого v. Время первого = S/v. Время второго = (S/2)/(v−9) + (S/2)/60. Приравниваем и делим на S, умножаем на 2:</p><p>2/v = 1/(v−9) + 1/60.</p><p>Приводя к общему виду: 2/v − 1/(v−9) = 1/60 ⟹ [2(v−9) − v]/[v(v−9)] = 1/60 ⟹ (v − 18)/[v(v−9)] = 1/60.</p><p>60(v − 18) = v² − 9v ⟹ v² − 69v + 1080 = 0 ⟹ v = (69 ± √(4761 − 4320))/2 = (69 ± 21)/2 = 45 или 24.</p><p>По условию v &gt; 40, поэтому v = 45 км/ч.</p>",
