		correct: "431",
		hint: "<p>По описанию и плану: Лягушкино — пункт ④ (откуда стартуют, слева внизу); шоссе идёт через Куровка ① и Марусино ③, где поворот налево к Вятскому ②. Значит Лягушкино = 4, Марусино = 3, Куровка = 1. Последовательность: 431.</p>",
