		title: "Часть 2 · График функции",
		body: "<p>Постройте график функции y = ((x − 1)(x² − 4)) / (x − 2) и определите, при каких значениях m прямая y = m имеет с графиком ровно одну общую точку.</p>",
		maxPoints: 2,
