		maxPoints: 2,
		hint: "<p>По свойству биссектрисы AC/BC = AM/MB = 13/15. Касательная DC и секущая дают DC² = DA·DB; треугольник DCM равнобедренный: DC = DM.</p><p>Так как AM &lt; MB, точка C ближе к B, и точка D лежит со стороны A. Пусть DA = d; тогда DB = d + 28, DM = d + 13, DC = d + 13. Подставляем в DC² = DA·DB:</p><p>(d + 13)² = d(d + 28) ⟹ d² + 26d + 169 = d² + 28d ⟹ 169 = 2d ⟹ d = 84,5.</p><p>CD = d + 13 = 84,5 + 13 = 97,5. (Проверка построением окружности подтверждает CD = 97,5.) Ответ: 97,5.</p>",
