		maxPoints: 2,
		hint: "<p>Пусть вторая труба пропускает v л/мин, первая — (v − 16). Время заполнения: первая 105/(v−16), вторая 105/v, разница 4 мин:</p><p>105/(v−16) − 105/v = 4.</p><p>105v − 105(v−16) = 4v(v−16)</p><p>1680 = 4v² − 64v</p><p>v² − 16v − 420 = 0</p><p>v = (16 + √(256 + 1680))/2 = (16 + 44)/2 = 30.</p><p>Вторая труба пропускает 30 л/мин.</p>",
