		maxPoints: 2,
		hint: "<p>Раскроем модуль.</p><p>• При x ≥ 0: y = x² − 3x − 2x = x² − 5x (парабола вверх, вершина (2,5; −6,25)).</p><p>• При x &lt; 0: y = x² + 3x − 2x = x² + x (парабола вверх, вершина (−0,5; −0,25)).</p><p>График: левая ветвь имеет локальный минимум −0,25, правая — минимум −6,25; в точке x = 0 значение 0.</p><p>Число точек пересечения с y = m:</p><p>– m &lt; −6,25: 0;</p><p>– m = −6,25: 1;</p><p>– −6,25 &lt; m &lt; −0,25: 2;</p><p>– m = −0,25: 3;</p><p>– −0,25 &lt; m &lt; 0: 4;</p><p>– m = 0: 3;</p><p>– m &gt; 0: 2.</p><p>Не менее одной и не более трёх точек — везде, кроме интервала с четырьмя точками. Ответ: m ∈ [−6,25; −0,25] ∪ [0; +∞).</p>",
