		body: "<p>Основания трапеции относятся как 3 : 7. Через точку пересечения диагоналей проведена прямая, параллельная основаниям. В каком отношении эта прямая делит площадь трапеции?</p>",
		maxPoints: 2,
		hint: "<p>Пусть основания BC = 3k и AD = 7k. Точка пересечения диагоналей O делит высоту трапеции в отношении 3 : 7 (считая от меньшего основания). Прямая через O параллельно основаниям имеет длину, равную среднему гармоническому оснований: EF = 2·BC·AD/(BC + AD) = 2·3k·7k/(10k) = 4,2k.</p><p>Высота от BC до EF: h₁ = H·3/10; от EF до AD: h₂ = H·7/10.</p><p>Площадь верхней части: S₁ = (BC + EF)/2·h₁ = (3k + 4,2k)/2·0,3H = 3,6k·0,3H = 1,08kH.</p><p>Площадь нижней части: S₂ = (EF + AD)/2·h₂ = (4,2k + 7k)/2·0,7H = 5,6k·0,7H = 3,92kH.</p><p>Отношение S₁ : S₂ = 1,08 : 3,92 = 108 : 392 = 27 : 98.</p>",
