		body: "<p>Форматы листов бумаги обозначают буквой A и цифрой: A0, A1, A2 и т.д. Лист A0 имеет площадь 1 кв. м; при разрезании пополам параллельно меньшей стороне получаются два листа следующего формата. Все форматы подобны.<br>В таблице даны размеры (с точностью до мм) четырёх листов форматов A2, A3, A4 и A6:<br>  лист 1: 594 × 420<br>  лист 2: 420 × 297<br>  лист 3: 148 × 105<br>  лист 4: 297 × 210<br>Установите соответствие между форматами и номерами листов. Запишите последовательность четырёх цифр для форматов A2, A3, A4, A6.</p><figure class=\"q-figure\"><img class=\"q-figure__img\" src=\"/img/mathematics/v18_formats.png\" alt=\"Иллюстрация к заданию ОГЭ по математике\" loading=\"lazy\" decoding=\"async\" /></figure>",
